INSERT INTO feature VALUES('declaration-tiers','editor','Each declaration''s kernel tier','language-server','partial','notable',NULL,'A lens above each declaration states how far the kernel certifies it, `kernel pending` until the document''s admission ends, then replayed, assumed with its body owed, refused, or withheld with its reason: a declaration it waits on by name, a form outside the fragment with the issue that owes its rule, or a static declaration. The session''s account keeps each tier by the declaration''s content key, and the document''s copy holds them, so no request computes one. A judgement shows the kept tier of each declaration whose content and verdict it did not change. A client that declares `experimental.kernelTiers` is notified each mark''s warrant and glyph when the admission ends, and the VS Code extension draws the glyph in the warrant''s colour. The compile tier and the attested verdict cache''s tier wait on the hub.','surface-lsp surface-dispatcher surface-session contrib/gandr-vscode','corpus/model/sessions/endpoint-loop.gandr crates/surface-lsp/src/server.rs crates/surface-dispatcher/src/compose.rs',NULL,'#6272');
